\label{tab:beta50}
\begin{tabular}{lcccc}
\toprule
$T$ & $\beta_{50}$ & $\beta_{50} \cdot \sqrt{T}$ & FPR (raw) & FPR (FDR) \\
\midrule
6  & ---  & ---  & 1\% & 0\% \\
